package com.example.restaurant.controller;import com.example.restaurant.repository.*;import com.example.restaurant.model.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/restaurants") public class RestaurantController{private final RestaurantRepository r;public RestaurantController(RestaurantRepository r){this.r=r;}@GetMapping public List<Restaurant> all(){return r.findAll();}}